import AppKit

/// The Settings sidebar's icons: the app's own drawings, one per pane, in place of SF
/// Symbols.
///
/// SVG source kept HERE, as text, rather than as files in a resource bundle: the `Ultra`
/// target ships no resources of its own, and eight small drawings do not earn it the
/// bundle, the copy step in `build-app.sh` and the lookup that can fail. AppKit reads
/// SVG directly. Each is a template — only its shape is used — so the sidebar draws it
/// in white on the pane's plate.
@MainActor
enum SettingsIcons {
    private static var cache: [SettingsPane: NSImage] = [:]

    /// A pane's icon, or nil if its drawing cannot be read — the caller falls back to
    /// the pane's SF Symbol.
    static func image(for pane: SettingsPane) -> NSImage? {
        if let cached = cache[pane] { return cached }
        guard let source = svg[pane], let image = NSImage(data: Data(source.utf8)) else { return nil }
        image.isTemplate = true
        cache[pane] = image
        return image
    }

    /// The drawings, each on a 24 × 24 box.
